properties.put("gw.path", "glob:**/*.java");
java.lang.Object result = tools.performAct("code-doc", new java.io.File("."), properties, false, org.machanism.macha.core.commons.configurator.Configurators.getConfigurator());

org.machanism.machai.gw.tools.WebFunctionTools tools = new org.machanism.machai.gw.tools.WebFunctionTools();
