headers.put("Authorization", "Bearer ${sonar.token}");
java.lang.String response = tools.callRestApi("${sonar.host}/api/issues/search", "GET", headers, "", 10000, "UTF-8", new java.io.File("."), org.machanism.macha.core.commons.configurator.Configurators.getConfigurator());

